import ast, hashlib, json, types
from pathlib import Path
base=Path('v2/experiments/action_executor')
paths=[base/'r19/qualification.py',base/'r21/test_r21_offline.py']
trees=[ast.parse(p.read_bytes()) for p in paths]
ns={}
for n in trees[0].body:
    if isinstance(n, ast.Assign) and any(isinstance(t,ast.Name) and t.id in {'PROFILES','OPERATIONS','STATUS','STATES'} for t in n.targets):
        exec(compile(ast.Module(body=[n],type_ignores=[]),str(paths[0]),'exec'),ns)
fn=next(n for n in trees[0].body if isinstance(n,ast.FunctionDef) and n.name=='expected')
exec(compile(ast.Module(body=[fn],type_ignores=[]),str(paths[0]),'exec'),ns)
prior=types.SimpleNamespace(expected=ns['expected'],STATUS=ns['STATUS'],STATES=ns['STATES'])
body=next(n for n in trees[1].body if isinstance(n,ast.ClassDef) and n.name=='R21Controls')
rows=next(n for n in body.body if isinstance(n,ast.FunctionDef) and n.name=='rows')
rns={'gate':types.SimpleNamespace(prior=prior)}
exec(compile(ast.Module(body=[rows],type_ignores=[]),str(paths[1]),'exec'),rns)
full=rns['rows'](None)
result={}
for name, data in [('full',full),('four',full[:4]),('one',full[:1])]:
    raw=json.dumps(data).encode()
    journal=''.join(json.dumps(row)+'\n' for row in data).encode()
    result[name]={'rows':len(data),'JSON_bytes':len(raw),'JSON_sha256':hashlib.sha256(raw).hexdigest(),'whole_JSONL_bytes':len(journal),'JSONL_sha256':hashlib.sha256(journal).hexdigest()}
print(json.dumps({'independent_exact_AST_function_selection_only':True,'source_hashes':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths},'payloads':result},sort_keys=True))
